'use server';

import { createSupabaseAdminClient } from "@/lib/supabase/server";
import { fetchMemberNickname } from "@/lib/name-api";

type UserWithDetails = {
    id: string;
    display_name: string;
    card_id: string | null;
    team_name: string | null;
    team_id: string | null;
    generation: number;
    is_admin: boolean;
    latest_attendance_type: string | null;
    latest_timestamp: string | null;
    deleted_at: string | null;
    student_number: string | null;
    status: number;
};

/**
 * すべてのユーザー情報を取得（管理画面用）
 */
export async function getAllUsersWithStatus(): Promise<{ data: UserWithDetails[], error: any }> {
    const supabase = await createSupabaseAdminClient();

    try {
        // member.membersからユーザー情報を取得
        const { data: members, error: membersError } = await supabase
            .schema('member')
            .from('members')
            .select(`
                supabase_auth_user_id,
                discord_uid,
                generation,
                is_admin,
                student_number,
                status,
                deleted_at,
                member_team_relations(team_id, teams(name))
            `);

        if (membersError) {
            console.error('Error fetching members:', membersError);
            return { data: [], error: membersError };
        }

        // attendance.usersからカード情報を取得
        const { data: attendanceUsers } = await supabase
            .schema('attendance')
            .from('users')
            .select('supabase_auth_user_id, card_id');

        const cardMap = new Map(attendanceUsers?.map(u => [u.supabase_auth_user_id, u.card_id]) || []);

        // 最新の打刻情報を取得
        const memberIds = members?.map((m: any) => m.supabase_auth_user_id) || [];
        const { data: latestAttendances } = await supabase
            .schema('attendance')
            .from('attendances')
            .select('user_id, type, timestamp')
            .in('user_id', memberIds)
            .order('timestamp', { ascending: false });

        // 各ユーザーの最新打刻を抽出
        const latestAttendanceMap = new Map<string, { type: string; timestamp: string }>();
        latestAttendances?.forEach((att: any) => {
            if (!latestAttendanceMap.has(att.user_id)) {
                latestAttendanceMap.set(att.user_id, { type: att.type, timestamp: att.timestamp });
            }
        });

        // Discord UIDから本名を一括取得（エラー耐性を持たせる）
        const discordUids = members?.map((m: any) => m.discord_uid).filter(Boolean) || [];
        const nameMap = new Map<string, string>();

        // 本名取得API呼び出し（エラーが発生しても続行）
        await Promise.allSettled(
            discordUids.map(async (discord_uid: string) => {
                try {
                    const { data: nickname, error } = await fetchMemberNickname(discord_uid);
                    if (nickname && !error) {
                        nameMap.set(discord_uid, nickname);
                    }
                } catch (error) {
                    // 個別のエラーは無視して続行
                    console.warn(`Failed to fetch nickname for ${discord_uid}:`, error);
                }
            })
        );

        // データを結合
        const users = members?.map((member: any) => {
            const latestAttendance = latestAttendanceMap.get(member.supabase_auth_user_id);
            const teamRelation = member.member_team_relations?.[0];
            const realName = member.discord_uid ? nameMap.get(member.discord_uid) : null;

            return {
                id: member.supabase_auth_user_id,
                display_name: realName || '名無しさん',
                card_id: cardMap.get(member.supabase_auth_user_id) || null,
                team_name: teamRelation?.teams?.name || null,
                team_id: teamRelation?.team_id || null,
                generation: member.generation,
                is_admin: member.is_admin,
                latest_attendance_type: latestAttendance?.type || null,
                latest_timestamp: latestAttendance?.timestamp || null,
                deleted_at: member.deleted_at,
                student_number: member.student_number,
                status: member.status ?? 0, // 0: 中学生, 1: 高校生, 2: OB/OG
            };
        }) || [];

        return { data: users, error: null };
    } catch (error) {
        console.error('Error in getAllUsersWithStatus:', error);
        return { data: [], error };
    }
}

/**
 * ユーザーの表示名を更新
 */
export async function updateUserDisplayName(userId: string, displayName: string) {
    const supabase = await createSupabaseAdminClient();

    const { error } = await supabase
        .schema('member')
        .from('members')
        .update({ display_name: displayName })
        .eq('supabase_auth_user_id', userId);

    return { success: !error, error };
}

/**
 * 全ユーザーの表示名を一括更新
 */
export async function updateAllUserDisplayNames() {
    const supabase = await createSupabaseAdminClient();

    try {
        const { data: members, error: fetchError } = await supabase
            .schema('member')
            .from('members')
            .select('supabase_auth_user_id, discord_uid');

        if (fetchError || !members) {
            return { success: false, message: 'ユーザーの取得に失敗しました。' };
        }

        let successCount = 0;
        let failCount = 0;

        // 並列処理で全ユーザーの名前を更新（エラー耐性）
        await Promise.allSettled(
            members.map(async (member: any) => {
                if (!member.discord_uid) return;

                try {
                    const { data: nickname, error } = await fetchMemberNickname(member.discord_uid);

                    if (nickname && !error) {
                        const { error: updateError } = await supabase
                            .schema('member')
                            .from('members')
                            .update({ display_name: nickname })
                            .eq('supabase_auth_user_id', member.supabase_auth_user_id);

                        if (!updateError) {
                            successCount++;
                        } else {
                            failCount++;
                        }
                    } else {
                        failCount++;
                    }
                } catch {
                    failCount++;
                }
            })
        );

        return {
            success: true,
            message: `更新完了: 成功 ${successCount}件、失敗 ${failCount}件`,
        };
    } catch (error) {
        console.error('Error updating all display names:', error);
        return { success: false, message: '更新中にエラーが発生しました。' };
    }
}

/**
 * ユーザーのカードIDを更新
 */
export async function updateUserCardId(userId: string, newCardId: string) {
    const supabase = await createSupabaseAdminClient();

    try {
        // カードIDを正規化（コロンを削除、小文字化）
        const normalizedCardId = newCardId.toLowerCase().replace(/:/g, '');

        // 既存のカードIDとの重複チェック
        const { data: existingUser, error: checkError } = await supabase
            .schema('attendance')
            .from('users')
            .select('supabase_auth_user_id')
            .eq('card_id', normalizedCardId)
            .neq('supabase_auth_user_id', userId)
            .single();

        if (existingUser) {
            return { success: false, message: 'このカードIDは既に使用されています。' };
        }

        // カードIDを更新
        const { error: updateError } = await supabase
            .schema('attendance')
            .from('users')
            .update({ card_id: normalizedCardId })
            .eq('supabase_auth_user_id', userId);

        if (updateError) {
            console.error('Error updating card ID:', updateError);
            return { success: false, message: 'カードIDの更新に失敗しました。' };
        }

        return { success: true, message: 'カードIDを更新しました。' };
    } catch (error) {
        console.error('Error in updateUserCardId:', error);
        return { success: false, message: '予期しないエラーが発生しました。' };
    }
}

import { createSupabaseServerClient } from "@/lib/supabase/server";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { subDays } from "date-fns";
import { ja } from "date-fns/locale";
import { redirect } from "next/navigation";
import { fetchMemberNickname } from "@/lib/name-api";
import { calculateTotalActivityTime } from "@/app/actions";
import { convertGenerationToGrade, formatJst } from "@/lib/utils";
import { Calendar as CalendarIcon, Clock, Percent, BarChart } from "lucide-react";
import AttendanceCalendar from "@/app/dashboard/components/AttendanceCalendar";
import { Button } from "@/components/ui/button";
import Link from "next/link";
import { ArrowLeft } from "lucide-react";
import {toZonedTime} from "date-fns-tz";

export const dynamic = 'force-dynamic';

const timeZone = 'Asia/Tokyo';

export default async function UserDetailPage({ params }: { params: Promise<{ userId: string }> }) {
    const resolvedParams = await params;
    const supabase = await createSupabaseServerClient();

    // 現在のユーザーが管理者かチェック
    const { data: { user: currentUser } } = await supabase.auth.getUser();
    if (!currentUser) {
        redirect('/login');
    }

    const { data: currentProfile } = await supabase
        .schema('member')
        .from('members')
        .select('is_admin')
        .eq('supabase_auth_user_id', currentUser.id)
        .single();

    if (!currentProfile?.is_admin) {
        redirect('/dashboard');
    }

    // 対象ユーザーの情報を取得
    const { data: profile, error: profileError } = await supabase
        .schema('member')
        .from('members')
        .select(`
            discord_uid,
            generation,
            joined_at,
            member_team_relations(teams(name))
        `)
        .eq('supabase_auth_user_id', resolvedParams.userId)
        .single();

    if (profileError || !profile) {
        redirect('/admin');
    }

    // Discord UIDから本名を取得
    let displayName = '名無しさん';
    try {
      if (profile.discord_uid) {
          const { data: nickname } = await fetchMemberNickname(profile.discord_uid);
          if (nickname) {
              displayName = nickname;
          }
      }
    } catch (e) {
      console.error('Failed to fetch nickname:', e);
    }

    const today = toZonedTime(new Date(), timeZone);
    const thirtyDaysAgo = formatJst(subDays(today, 30), 'yyyy-MM-dd');
    const userCreatedAtDate = formatJst(new Date(profile.joined_at), 'yyyy-MM-dd');

    const [attendancesResult, totalActivityTime] = await Promise.all([
      supabase.schema('attendance').from('attendances').select('*').eq('user_id', resolvedParams.userId).order('timestamp', { ascending: false }).limit(10),
      calculateTotalActivityTime(resolvedParams.userId, 30)
    ]);

    const { data: attendances } = attendancesResult;

    const { data: distinctDates } = await supabase
      .schema('attendance')
      .from('attendances')
      .select('date')
      .eq('user_id', resolvedParams.userId)
      .eq('type', 'in')
      .gte('date', thirtyDaysAgo);

    const userAttendanceDays = distinctDates ? new Set(distinctDates.map(d => d.date)).size : 0;

    const { data: totalClubActivityDates } = await supabase
      .schema('attendance')
      .from('attendances')
      .select('date')
      .eq('type', 'in')
      .gte('date', thirtyDaysAgo)
      .gte('date', userCreatedAtDate); 

    const totalClubDays = totalClubActivityDates ? new Set(totalClubActivityDates.map(d => d.date)).size : 0;

    const attendanceRate = totalClubDays > 0 ? (userAttendanceDays / totalClubDays) * 100 : 0;

    const teamName = profile?.member_team_relations?.[0]?.teams?.name;

  return (
    <div className="space-y-6">
        <div className="flex items-center gap-4">
            <Button variant="outline" size="icon" asChild>
                <Link href="/admin">
                    <ArrowLeft className="h-4 w-4" />
                </Link>
            </Button>
            <div className="flex-1">
                <h1 className="text-3xl font-bold">{displayName}さんの出席詳細</h1>
                <p className="text-muted-foreground">
                    {teamName && <Badge variant="secondary" className="mr-2">{teamName}</Badge>}
                    {profile?.generation && convertGenerationToGrade(profile.generation)}
                </p>
            </div>
        </div>

        <div className="grid gap-4 grid-cols-1 sm:grid-cols-2 lg:grid-cols-4">
            <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">出勤日数</CardTitle>
                    <CalendarIcon className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                    <div className="text-2xl font-bold">{userAttendanceDays}日</div>
                     <p className="text-xs text-muted-foreground">
                        過去30日間
                    </p>
                </CardContent>
            </Card>
            <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">活動時間 (概算)</CardTitle>
                    <Clock className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                    <div className="text-2xl font-bold">{totalActivityTime.toFixed(1)} 時間</div>
                    <p className="text-xs text-muted-foreground">
                        過去30日間
                    </p>
                </CardContent>
            </Card>
            <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">出勤率</CardTitle>
                    <Percent className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                    <div className="text-2xl font-bold">{attendanceRate.toFixed(1)}%</div>
                    <p className="text-xs text-muted-foreground">
                        活動日数(登録後): {totalClubDays}日
                    </p>
                </CardContent>
            </Card>
            <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">直近の活動</CardTitle>
                    <BarChart className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                    <div className="text-2xl font-bold">{attendances && attendances.length > 0 ? (attendances[0].type === 'in' ? '活動中' : '退勤済み') : '記録なし'}</div>
                </CardContent>
            </Card>
      </div>

      <div className="grid gap-6">
            <Card>
                <CardHeader>
                    <CardTitle>最近の出退勤記録</CardTitle>
                </CardHeader>
                <CardContent>
                    <Table>
                        <TableHeader>
                            <TableRow>
                            <TableHead>種別</TableHead>
                            <TableHead>日時</TableHead>
                            <TableHead>カードID</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {attendances && attendances.length > 0 ? attendances.map((att) => (
                                <TableRow key={att.id}>
                                    <TableCell>
                                        <Badge variant={att.type === 'in' ? 'default' : 'secondary'}>
                                            {att.type === 'in' ? '出勤' : '退勤'}
                                        </Badge>
                                    </TableCell>
                                    <TableCell>{formatJst(new Date(att.timestamp), 'yyyy/MM/dd HH:mm:ss')}</TableCell>
                                    <TableCell className="font-mono text-sm">{att.card_id}</TableCell>
                                </TableRow>
                            )) : (
                                <TableRow>
                                    <TableCell colSpan={3} className="text-center">記録がありません。</TableCell>
                                </TableRow>
                            )}
                        </TableBody>
                    </Table>
                </CardContent>
            </Card>
             <Card>
                <CardHeader>
                <CardTitle>出勤カレンダー</CardTitle>
                </CardHeader>
                <CardContent>
                    <AttendanceCalendar userId={resolvedParams.userId} />
                </CardContent>
            </Card>
        </div>
    </div>
  );
}

